@sig trait TargetStepReadinessQualifier_Api {
  def id: Art.BridgeId
  def readinessObservation_Id : Art.PortId
  def flowContext_Id : Art.PortId
  def targetFact_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var targetFact: Factory_Flow.TargetQualification.Type = $

  def put_targetFact(value : Factory_Flow.TargetQualification.Type) : Unit = {
    Contract(
      Modifies(targetFact),
      Ensures(
        targetFact == value
      )
    )
    Spec {
      targetFact = value
    }

    Art.putValue(targetFact_Id, Factory_Flow.TargetQualification_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class TargetStepReadinessQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val readinessObservation_Id : Art.PortId,
  val flowContext_Id : Art.PortId,
  val targetFact_Id : Art.PortId) extends TargetStepReadinessQualifier_Api

