        None[Factory_Flow.StepReadinessObservation]()
      case _ => None[Factory_Flow.StepReadinessObservation]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var flowContext: Factory_Flow.FlowContext = $

  def get_flowContext() : Option[Factory_Flow.FlowContext] = {
